CREATE FUNCTION gridex_ediel_ack_guide.projection_for_original_v1(p_source_version text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE original jsonb;known jsonb;n integer;
BEGIN
 original:=gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(p_source_version);
 IF original ? 'utiltsErrReasonGuideScopes' THEN RETURN original;END IF;
 SELECT count(*) INTO n FROM gridex_ediel_ack_guide.err_reason_source_editions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.source_version
  WHERE e.projection->'constraints'=original->'constraints' AND e.projection->'utiltsErr'=original->'utiltsErr'
   AND e.projection->'registeredGuideScopes'=original->'registeredGuideScopes' AND e.projection->'originalSources'=original->'originalSources';
 SELECT e.projection INTO known FROM gridex_ediel_ack_guide.err_reason_source_editions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.source_version
  WHERE e.projection->'constraints'=original->'constraints' AND e.projection->'utiltsErr'=original->'utiltsErr'
   AND e.projection->'registeredGuideScopes'=original->'registeredGuideScopes' AND e.projection->'originalSources'=original->'originalSources';
 IF n<>1 OR known IS NULL THEN RAISE EXCEPTION 'ediel_original_err_reason_scope_unavailable';END IF;
 -- Supplemental source knowledge only: no new reception/version/acceptance.
 RETURN original||jsonb_build_object('utiltsErrReasonGuideScopes',known->'utiltsErrReasonGuideScopes');
END $$;
CREATE FUNCTION gridex_ediel_ack_guide.qualify_err_reason_projection_v1(p_projection jsonb,p_basis jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE r jsonb:=p_basis#>'{snapshot,rulePack}';reasons jsonb;n integer;
BEGIN
 IF r->>'family' IS DISTINCT FROM 'UTILTS' THEN RETURN p_projection;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(p_projection->'utiltsErrReasonGuideScopes')s
  WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 SELECT s->'allowedReasons' INTO reasons FROM jsonb_array_elements(p_projection->'utiltsErrReasonGuideScopes')s
  WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 IF n<>1 OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)=0 THEN RAISE EXCEPTION 'ediel_original_err_reason_scope_unavailable';END IF;
 RETURN jsonb_set(p_projection,'{utiltsErr,allowedReasons}',reasons,false);
END $$;
-- Patch the existing national native checker, preserving outer P-scope and
-- provider-replay wrappers. No independent ERR validator or timer is added.
DO $same_owner$ DECLARE definition text;needle text;BEGIN
 definition:=pg_get_functiondef('gridex_ediel_ack_guide.require_before_prodat_scope_v1(public.ediel_messages)'::regprocedure);
 needle:='projection:=gridex_ediel_ack_guide.projection_for_original_v1(b.source_version);';
 IF position(needle IN definition)=0 THEN RAISE EXCEPTION 'ediel_err_reason_owner_contract_mismatch';END IF;
 EXECUTE replace(definition,needle,needle||'projection:=gridex_ediel_ack_guide.qualify_err_reason_projection_v1(projection,basis);');
END $same_owner$;
REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(text),gridex_ediel_ack_guide.projection_for_original_v1(text),gridex_ediel_ack_guide.qualify_err_reason_projection_v1(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
